class Solution {
public:
    int longestBalanced(string s) {
        int n = (int)s.size();

        int total0 = 0, total1 = 0;
        for (char c : s) {
            if (c == '0') ++total0;
            else ++total1;
        }

        int offset = n + 2;
        vector<vector<int>> pos(2 * n + 5);

        int balance = 0;
        int ans = 0;

        pos[offset].push_back(0);

        for (int i = 1; i <= n; ++i) {
            balance += (s[i - 1] == '1') ? 1 : -1;
            int cur = balance + offset;

            // No swap required.
            if (!pos[cur].empty()) {
                ans = max(ans, i - pos[cur][0]);
            }

            // Substring balance +2.
            int target = cur - 2;
            if (target >= 0 && !pos[target].empty()
                && total0 > 0) {

                // Length <= 2 * total0
                int minStart = i - 2 * total0;

                auto it = lower_bound(
                    pos[target].begin(),
                    pos[target].end(),
                    minStart
                );

                if (it != pos[target].end()) {
                    ans = max(ans, i - *it);
                }
            }

            // Substring balance -2.
            target = cur + 2;
            if (target < (int)pos.size()
                && !pos[target].empty()
                && total1 > 0) {

                // Length <= 2 * total1
                int minStart = i - 2 * total1;

                auto it = lower_bound(
                    pos[target].begin(),
                    pos[target].end(),
                    minStart
                );

                if (it != pos[target].end()) {
                    ans = max(ans, i - *it);
                }
            }

            pos[cur].push_back(i);
        }

        return ans;
    }
};
